CHILD_TYPES={"AMENDMENT_REGISTRATION","T1_STATISTICAL_TRIAL","WAVE1_STATISTICAL_TRIAL"}
PROHIBITED={"H2","D4","H3","E2","MAINNET","CAPITAL","EXCHANGE_API_KEY","HOME_REAL_MARKET","S2A","P1","P2","P4","NEW_FAMILY","NEW_CANDIDATE","NEW_SCIENTIFIC_GRAMMAR","NEW_DATASET_REVISION","NEW_LABEL_WINDOW","SIGN_FLIP","SURVIVOR_ADMISSION","VALIDATED_ALPHA","P5_STRATEGY_PASS"}

# RFC 8032 Ed25519 verification, stdlib-only. Production never holds a private
# key and the research daemon does not shell out to openssl/subprocess.
_Q=2**255-19
_L=2**252+27742317777372353535851937790883648493
_D=(-121665*pow(121666,_Q-2,_Q))%_Q
_I=pow(2,(_Q-1)//4,_Q)
_IDENTITY=(0,1)
def _xrecover(y:int,sign:int)->int:
    xx=((y*y-1)*pow((_D*y*y+1)%_Q,_Q-2,_Q))%_Q
    x=pow(xx,(_Q+3)//8,_Q)
    if (x*x-xx)%_Q:x=(x*_I)%_Q
    if (x*x-xx)%_Q:raise ValueError('point is not on curve')
    if (x&1)!=sign:x=_Q-x
    return x
def _decode_point(raw:bytes)->tuple[int,int]:
    if len(raw)!=32:raise ValueError('encoded point length')
    n=int.from_bytes(raw,'little');sign=n>>255;y=n&((1<<255)-1)
    if y>=_Q:raise ValueError('noncanonical point')
    p=(_xrecover(y,sign),y)
    if _encode_point(p)!=raw:raise ValueError('noncanonical point encoding')
    return p
def _encode_point(p:tuple[int,int])->bytes:
    x,y=p;return (y|((x&1)<<255)).to_bytes(32,'little')
def _add(p:tuple[int,int],q:tuple[int,int])->tuple[int,int]:
    x1,y1=p;x2,y2=q;t=(_D*x1*x2*y1*y2)%_Q
    return (((x1*y2+x2*y1)*pow((1+t)%_Q,_Q-2,_Q))%_Q,
            ((y1*y2+x1*x2)*pow((1-t)%_Q,_Q-2,_Q))%_Q)
def _mul(p:tuple[int,int],n:int)->tuple[int,int]:
    out=_IDENTITY;cur=p
    while n:
        if n&1:out=_add(out,cur)
        cur=_add(cur,cur);n>>=1
    return out
_BY=(4*pow(5,_Q-2,_Q))%_Q
_B=(_xrecover(_BY,0),_BY)
def verify_ed25519(public_key:bytes,message:bytes,signature:bytes)->None:
    if len(public_key)!=32 or len(signature)!=64:raise ValueError('Ed25519 length')
    a=_decode_point(public_key);rraw=signature[:32];r=_decode_point(rraw)
    s=int.from_bytes(signature[32:],'little')
    if s>=_L:raise ValueError('noncanonical scalar')
    if _mul(a,8)==_IDENTITY or _mul(r,8)==_IDENTITY:raise ValueError('small-order point')
    h=int.from_bytes(hashlib.sha512(rraw+public_key+message).digest(),'little')%_L
    if _encode_point(_mul(_B,s))!=_encode_point(_add(r,_mul(a,h))):
        raise ValueError('invalid Ed25519 signature')

def _utc(x:str)->datetime:
    if not x.endswith('Z'):raise AuthorityError('UTC timestamp required')
    return datetime.fromisoformat(x[:-1]+'+00:00').astimezone(timezone.utc)

@dataclass(frozen=True)
