class DelegationVerifier:
    def __init__(self, owner_public_key_raw:bytes):
        if len(owner_public_key_raw)!=32:raise AuthorizationDenied('invalid owner public key')
        self._key=owner_public_key_raw
        self._revoked:set[str]=set();self._redeemed:set[tuple[str,str]]=set();self._amendments:list[str]=[]
    def verify_signature(self,d:OwnerConditionalDelegation)->None:
        if d.owner_credential_scheme!='ED25519':raise AuthorizationDenied('unsupported owner credential scheme')
        validate_resource_policy(d.resource_policy)
        if d.amendment_c_sha256 in d.allowed_amendment_hashes:
            raise AuthorizationDenied('D_CAN_AUTHORIZE_C=NO')
        if d.amendment_d_sha256 not in d.allowed_amendment_hashes:
            raise AuthorizationDenied('AMENDMENT_D_BINDING_REQUIRED')
        try:verify_ed25519(self._key,canonical_json(d.unsigned_payload()),base64.b64decode(d.owner_signature,validate=True))
        except ValueError as exc:raise AuthorizationDenied('invalid owner signature') from exc
    def revoke(self,delegation_id:str,ctx:DaemonContext,owner_peer_uid:int)->None:
        if ctx.peer_uid!=owner_peer_uid:raise AuthorizationDenied('owner-only revocation')
        self._revoked.add(delegation_id)
    def redeem(self,d:OwnerConditionalDelegation,p:ChildProposal,preconditions_event:Mapping[str,Any],ctx:DaemonContext)->dict[str,Any]:
        self.verify_signature(d)
        if d.delegation_id in self._revoked or d.revocation_state!='ACTIVE':raise AuthorizationDenied('delegation revoked')
        if _utc(ctx.recorded_at)>=_utc(d.expires_at):raise AuthorizationDenied('delegation expired')
        if p.producer_session_id==d.owner_session_id:raise AuthorizationDenied('owner/producer session separation failed')
        if preconditions_event.get('to')!='PRECONDITIONS_PASS':raise AuthorizationDenied('PRECONDITIONS_PASS absent')
        if int(preconditions_event.get('ledger_sequence',-1))>=ctx.ledger_sequence:raise AuthorizationDenied('redemption must follow preconditions')
        if p.proposal_type not in d.allowed_child_authority_types or p.proposal_type not in CHILD_TYPES:raise AuthorizationDenied('child type outside delegation')
        if p.proposal_type=='AMENDMENT_REGISTRATION' and p.amendment_hash==d.amendment_c_sha256:
            raise AuthorizationDenied('root delegation cannot register Amendment C')
        exact=[(p.campaign,d.allowed_campaign),(p.family,d.allowed_family),(p.run_class in d.allowed_run_classes,True),(p.evidence_domain in d.allowed_evidence_domains,True),(p.scientific_root_hash in d.allowed_scientific_root_hashes,True),(p.dataset_manifest_hash,d.allowed_dataset_manifest_hash),(p.revision_hash,d.allowed_revision_hash),(p.pit_rule_hash,d.allowed_pit_rule_hash),(p.candidate_list_hash,d.allowed_candidate_list_hash),(p.candidate_grammar_hash,d.allowed_candidate_grammar_hash),(p.enumerator_hash,d.allowed_enumerator_hash),(p.evaluation_order_hash,d.allowed_evaluation_order_hash),(p.scientific_contract_hash,d.allowed_scientific_contract_hash),(p.evaluator_hash,d.allowed_evaluator_hash),(p.t1_prereg_hash,d.allowed_t1_prereg_hash),(p.integrity_void_contract_hash,d.allowed_integrity_void_contract_hash)]
        if not all(a==b for a,b in exact):raise AuthorizationDenied('DELEGATION_SCOPE_MATCH failed')
        if p.proposal_type=='WAVE1_STATISTICAL_TRIAL':
            if p.resource_policy is None:
                raise AuthorizationDenied('RESOURCE_POLICY_MISSING')
            if resource_policy_sha256(p.resource_policy)!=resource_policy_sha256(d.resource_policy):
                raise AuthorizationDenied('RESOURCE_POLICY_BINDING_MISMATCH')
        elif p.resource_policy is not None:
            raise AuthorizationDenied('RESOURCE_POLICY_UNEXPECTED_FOR_CHILD')
        if p.amendment_hash is not None and p.amendment_hash not in d.allowed_amendment_hashes:raise AuthorizationDenied('amendment hash outside delegation')
        predicates=(p.evaluator_registered,p.twenty_object_gate_pass,p.scientific_rule_changes==0,p.zero_llm,p.no_network,p.no_rng,p.float64,p.byte_identical_double_run,p.all_mandatory_goldens_pass,p.synthetic_benchmark_pass,p.pc7_evaluator_pass,p.research_memory_pass)
        if not all(predicates):raise AuthorizationDenied('frozen evaluator predicates failed')
        if not set(p.information_domains)<=set(d.allowed_information_domains):raise AuthorizationDenied('information-domain expansion')
        if set(p.requested_rights)&PROHIBITED or set(p.requested_rights)&set(d.explicit_prohibitions):raise AuthorizationDenied('prohibited right requested')
        key=(d.delegation_id,p.proposal_id)
        if key in self._redeemed:raise AuthorizationDenied('duplicate logical grant redemption')
        self._redeemed.add(key)
        sig_hash=hashlib.sha256(base64.b64decode(d.owner_signature)).hexdigest()
        event={'from':'PRECONDITIONS_PASS','to':'HUMAN_OWNER_SIGNED','authorization_mode':'PREAUTHORIZED_CONDITIONAL_DELEGATION','parent_delegation_id':d.delegation_id,'parent_owner_signature_hash':sig_hash,'child_proposal_id':p.proposal_id,'preconditions_event_id':preconditions_event['event_id'],'scope_hash':d.scope_hash,'resource_policy_sha256':resource_policy_sha256(d.resource_policy) if p.proposal_type=='WAVE1_STATISTICAL_TRIAL' else None,'redemption_event_id':'redeem-'+hashlib.sha256(canonical_json({'d':d.delegation_id,'p':p.proposal_id,'seq':ctx.ledger_sequence})).hexdigest()[:32],'daemon_recorded_at':ctx.recorded_at,'ledger_sequence':ctx.ledger_sequence,'immutable_session_id':ctx.session_id,'authorization_source':'HUMAN_OWNER_PREAUTHORIZED_CREDENTIAL','agent_signed':False}
        return event
    def register_amendment(self,amendment_id:str,amendment_hash:str,d:OwnerConditionalDelegation)->dict[str,Any]:
        # Delegated mode starts only after direct-owner C and D are APPLIED.
        # It can register exact A then B and can never register C or D.
        if amendment_id in {'C','D'}:raise AuthorizationDenied('root delegation cannot register C or D')
        expected=('A','B');idx=len(self._amendments)
        if idx>=2 or amendment_id!=expected[idx]:raise AuthorizationDenied('A->B order violation')
        if amendment_hash not in d.allowed_amendment_hashes:raise AuthorizationDenied('wrong amendment hash')
        self._amendments.append(amendment_id);return {'event_type':'AMENDMENT_REGISTERED','amendment_id':amendment_id,'ordinal':idx+1}

def wave1_continuation_allowed(t1_state:str)->bool:
    if t1_state=='TEST_VOIDED':return False
    if t1_state not in {'REPLICATION_SUPPORTED','REPLICATION_FAILED','EVIDENCE_INSUFFICIENT_CURRENT_COHORT'}:raise AuthorityError('unknown T1 state')
    return True

def require_complete_frozen_wave(candidate_count:int,completed:int,integrity_failure:bool)->None:
    if integrity_failure:raise AuthorityError('integrity failure stops wave')
    if candidate_count!=174 or completed!=174:raise AuthorityError('all 174 candidates required; no performance early stop')

"""Daemon-only P5 authority persistence backed by append-only schema v3."""
from __future__ import annotations
import base64, hashlib, json, os
from dataclasses import replace
from pathlib import Path
from typing import Any
import apsw
try:
    from .research_db import FailClosed, canonical_json
    from .conditional_delegation import OwnerConditionalDelegation, ChildProposal, DelegationVerifier
    from .authority_runtime import DaemonContext, FrozenBindings, resource_policy_sha256
except ImportError:
    from research_db import FailClosed, canonical_json
    from conditional_delegation import OwnerConditionalDelegation, ChildProposal, DelegationVerifier
    from authority_runtime import DaemonContext, FrozenBindings, resource_policy_sha256

AMENDMENT_A_SHA256="495ad47fed0210ba4b495bdd86aa28784a5e5594df1e2648b6e04de8aa1fa379"
AMENDMENT_B_SHA256="fa85f7033226c497262418aa1c7bba0eddcb1a340febcf36a5643aa3bddc52bf"
AMENDMENT_C_SHA256="5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83"

def _sha(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode()).hexdigest()

def _hash64(value: str, code: str) -> str:
    if len(value) != 64 or any(ch not in "0123456789abcdef" for ch in value):
        raise FailClosed(code)
    return value

def _amendment_d_sha256() -> str:
    return _hash64(os.environ.get("P5_AMENDMENT_D_SHA256", ""), "AMENDMENT_D_HASH_NOT_PINNED")

def _expected_amendment_hash(amendment_id: str) -> str:
    return {"A": AMENDMENT_A_SHA256, "B": AMENDMENT_B_SHA256,
            "C": AMENDMENT_C_SHA256, "D": _amendment_d_sha256()}[amendment_id]

def _owner_key() -> bytes:
    path = os.environ.get("P5_OWNER_ED25519_PUBLIC_KEY_FILE", "")
    if not path or not Path(path).is_file():
        raise FailClosed("OWNER_PUBLIC_KEY_NOT_CONFIGURED")
    raw = Path(path).read_bytes()
    if len(raw) != 32:
        raise FailClosed("OWNER_PUBLIC_KEY_INVALID")
    return raw

def _owner_uid() -> int:
    return int(os.environ.get("P5_OWNER_PEER_UID", "-1"))

class AuthorityStore:
    def __init__(self, db_path: Path):
        self.db_path = db_path

    def _open(self):
        con = apsw.Connection(str(self.db_path)); con.set_busy_timeout(2000)
        con.execute("PRAGMA foreign_keys=ON")
        return con

    def proposal(self, payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); bindings = FrozenBindings(**payload["bindings"]).validate()
        proposal_id = str(payload["proposal_id"]); binding_json = canonical_json(vars(bindings))
        resource_hash = resource_policy_sha256(bindings.resource_scope) if bindings.wave_id is not None else None
        con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            con.execute("INSERT INTO authority_proposals(proposal_id,family_id,run_id,run_class,binding_sha256,binding_json,producer_session_id,expires_at,created_at,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?)", (proposal_id,bindings.family_id,bindings.run_id,bindings.run_class,bindings.digest,binding_json,ctx.session_id,str(payload["expires_at"]),ctx.recorded_at,resource_hash))
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)", (proposal_id,"NONE","PROPOSED",ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({"p":proposal_id,"to":"PROPOSED","seq":ctx.ledger_sequence}),resource_hash))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","proposal_id":proposal_id,"state":"PROPOSED","binding_sha256":bindings.digest}

    def transition(self, proposal_id: str, target: str, ctx: DaemonContext, observed_binding_sha256: str|None=None) -> dict[str, Any]:
        ctx.validate(); con = self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row = con.execute("SELECT binding_sha256,producer_session_id,expires_at,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",(proposal_id,)).fetchone()
            if not row: raise FailClosed("PROPOSAL_NOT_FOUND")
            last = con.execute("SELECT to_state FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1",(proposal_id,)).fetchone()
            current = last[0]; wanted={"PROPOSED":"PRECONDITIONS_PASS","PRECONDITIONS_PASS":"HUMAN_OWNER_SIGNED","HUMAN_OWNER_SIGNED":"APPLIED"}.get(current)
            if target != wanted: raise FailClosed("ILLEGAL_AUTHORITY_TRANSITION")
            if target == "PRECONDITIONS_PASS" and observed_binding_sha256 != row[0]: raise FailClosed("BINDING_MISMATCH")
            if target == "HUMAN_OWNER_SIGNED":
                if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
                if ctx.session_id == row[1]: raise FailClosed("OWNER_SESSION_SEPARATION_FAILED")
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(proposal_id,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({"p":proposal_id,"to":target,"seq":ctx.ledger_sequence}),row[3]))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","proposal_id":proposal_id,"state":target}

    def register_delegation(self, payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); delegation=OwnerConditionalDelegation(**payload); verifier=DelegationVerifier(_owner_key()); verifier.verify_signature(delegation)
        if delegation.amendment_a_sha256 != AMENDMENT_A_SHA256 or delegation.amendment_b_sha256 != AMENDMENT_B_SHA256 or delegation.amendment_c_sha256 != AMENDMENT_C_SHA256 or delegation.amendment_d_sha256 != _amendment_d_sha256():
            raise FailClosed("ROOT_AMENDMENT_BINDING_MISMATCH")
        signature=base64.b64decode(delegation.owner_signature,validate=True); resource_hash=resource_policy_sha256(delegation.resource_policy)
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            observed=list(con.execute("SELECT amendment_id,amendment_sha256,authorization_mode,state FROM amendment_registrations ORDER BY registration_ordinal"))
            expected=[("C",AMENDMENT_C_SHA256,"INTERACTIVE_OWNER_SIGN","APPLIED"),("D",_amendment_d_sha256(),"INTERACTIVE_OWNER_SIGN","APPLIED")]
            if observed != expected: raise FailClosed("EXACT_C_AND_D_DIRECT_OWNER_APPLIED_REQUIRED")
            con.execute("INSERT INTO owner_conditional_delegations(delegation_id,owner_identity,owner_credential_scheme,unsigned_payload_json,owner_signature_b64,owner_signature_sha256,owner_session_id,expires_at,scope_sha256,state,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(delegation.delegation_id,delegation.owner_identity,delegation.owner_credential_scheme,canonical_json(delegation.unsigned_payload()),delegation.owner_signature,hashlib.sha256(signature).hexdigest(),delegation.owner_session_id,delegation.expires_at,delegation.scope_hash,"ACTIVE",resource_hash))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","delegation_id":delegation.delegation_id,"scope_sha256":delegation.scope_hash}

    def redeem(self, delegation_id: str, proposal_payload: dict[str, Any], ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate(); con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row=con.execute("SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?",(delegation_id,)).fetchone()
            if not row: raise FailClosed("DELEGATION_NOT_FOUND")
            raw=json.loads(row[0]); raw["owner_signature"]=row[1]; delegation=OwnerConditionalDelegation(**raw); proposal=ChildProposal(**proposal_payload)
            canonical=con.execute("SELECT producer_session_id,binding_json,resource_policy_sha256 FROM authority_proposals WHERE proposal_id=?",(proposal.proposal_id,)).fetchone()
            if not canonical: raise FailClosed("PROPOSAL_NOT_FOUND")
            proposal=replace(proposal,producer_session_id=canonical[0]); binding=json.loads(canonical[1])
            if proposal.family!=binding["family_id"] or proposal.run_class!=binding["run_class"] or proposal.evidence_domain!=binding["evidence_domain"] or proposal.evaluator_hash!=binding["evaluator_sha256"]: raise FailClosed("CANONICAL_PROPOSAL_SCOPE_MISMATCH")
            if proposal.proposal_type=="WAVE1_STATISTICAL_TRIAL" and (proposal.resource_policy is None or resource_policy_sha256(proposal.resource_policy)!=canonical[2]): raise FailClosed("RESOURCE_POLICY_BINDING_MISMATCH")
            pre=con.execute("SELECT transition_id,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? AND to_state='PRECONDITIONS_PASS' ORDER BY transition_id DESC LIMIT 1",(proposal.proposal_id,)).fetchone()
            if not pre: raise FailClosed("PRECONDITIONS_PASS_ABSENT")
            if con.execute("SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?",(delegation_id,)).fetchone(): raise FailClosed("DELEGATION_REVOKED")
            event=DelegationVerifier(_owner_key()).redeem(delegation,proposal,{"to":"PRECONDITIONS_PASS","ledger_sequence":pre[1],"event_id":str(pre[0])},ctx)
            con.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?,?,?)",(proposal.proposal_id,"PRECONDITIONS_PASS","HUMAN_OWNER_SIGNED",ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha(event),event.get("resource_policy_sha256")))
            transition_id=con.last_insert_rowid()
            con.execute("INSERT INTO delegation_redemptions(redemption_event_id,delegation_id,child_proposal_id,preconditions_transition_id,human_owner_signed_transition_id,scope_sha256,resource_policy_sha256) VALUES(?,?,?,?,?,?,?)",(event["redemption_event_id"],delegation_id,proposal.proposal_id,pre[0],transition_id,event["scope_hash"],event.get("resource_policy_sha256")))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","event":event}

    def revoke(self, delegation_id: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
        event_id="revoke-"+_sha({"d":delegation_id,"seq":ctx.ledger_sequence})[:32]; con=self._open()
        try: con.execute("INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)",(event_id,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))
        finally: con.close()
        return {"status":"PASS","event":"OWNER_DELEGATION_REVOKED","revocation_event_id":event_id}

    def register_amendment(self, delegation_id: str, amendment_id: str, amendment_hash: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if amendment_id not in {"A","B"}: raise FailClosed("ROOT_CANNOT_REGISTER_C_OR_D")
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            row=con.execute("SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?",(delegation_id,)).fetchone()
            if not row: raise FailClosed("DELEGATION_NOT_FOUND")
            if con.execute("SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?",(delegation_id,)).fetchone(): raise FailClosed("DELEGATION_REVOKED")
            raw=json.loads(row[0]); raw["owner_signature"]=row[1]; delegation=OwnerConditionalDelegation(**raw); DelegationVerifier(_owner_key()).verify_signature(delegation)
            observed=[item[0] for item in con.execute("SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal")]
            expected=["C","D","A","B"]
            if observed!=expected[:len(observed)] or len(observed)>=4 or amendment_id!=expected[len(observed)]: raise FailClosed("C_D_A_B_ORDER_VIOLATION")
            exact={"A":delegation.amendment_a_sha256,"B":delegation.amendment_b_sha256}
            if amendment_hash!=exact[amendment_id] or amendment_hash!=_expected_amendment_hash(amendment_id): raise FailClosed("AMENDMENT_ID_HASH_BINDING_MISMATCH")
            event_id="amend-"+_sha({"d":delegation_id,"a":amendment_id,"seq":ctx.ledger_sequence})[:32]
            con.execute("INSERT INTO amendment_registrations(amendment_event_id,amendment_id,amendment_sha256,registration_ordinal,authorization_mode,delegation_id,daemon_recorded_at,daemon_ledger_sequence,authenticated_owner_uid,producer_session_id,owner_session_id,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(event_id,amendment_id,amendment_hash,len(observed)+1,"PREAUTHORIZED_CONDITIONAL_DELEGATION",delegation_id,ctx.recorded_at,ctx.ledger_sequence,None,ctx.session_id,delegation.owner_session_id,"APPLIED"))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","amendment_event_id":event_id,"amendment_id":amendment_id,"registration_ordinal":len(observed)+1,"state":"APPLIED"}

    def register_amendment_direct(self, amendment_id: str, amendment_hash: str, producer_session_id: str, ctx: DaemonContext) -> dict[str, Any]:
        ctx.validate()
        if ctx.peer_uid != _owner_uid(): raise FailClosed("OWNER_CREDENTIAL_REQUIRED")
        if not producer_session_id or producer_session_id==ctx.session_id: raise FailClosed("OWNER_SESSION_SEPARATION_FAILED")
        if amendment_id not in {"C","D"}: raise FailClosed("DIRECT_OWNER_ONLY_C_OR_D")
        if amendment_hash != _expected_amendment_hash(amendment_id): raise FailClosed("AMENDMENT_ID_HASH_BINDING_MISMATCH")
        con=self._open()
        try:
            con.execute("BEGIN IMMEDIATE")
            observed=[row[0] for row in con.execute("SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal")]
            expected=["C","D"]
            if observed!=expected[:len(observed)] or len(observed)>=2 or amendment_id!=expected[len(observed)]: raise FailClosed("C_FIRST_D_SECOND_REQUIRED")
            event_id="amend-direct-"+_sha({"a":amendment_id,"h":amendment_hash,"seq":ctx.ledger_sequence})[:32]
            con.execute("INSERT INTO amendment_registrations(amendment_event_id,amendment_id,amendment_sha256,registration_ordinal,authorization_mode,delegation_id,daemon_recorded_at,daemon_ledger_sequence,authenticated_owner_uid,producer_session_id,owner_session_id,state) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",(event_id,amendment_id,amendment_hash,len(observed)+1,"INTERACTIVE_OWNER_SIGN",None,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid,producer_session_id,ctx.session_id,"APPLIED"))
            con.execute("COMMIT")
        except BaseException:
            if not con.getautocommit(): con.execute("ROLLBACK")
            raise
        finally: con.close()
        return {"status":"PASS","amendment_event_id":event_id,"amendment_id":amendment_id,"registration_ordinal":len(observed)+1,"state":"APPLIED"}

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}

RESOURCE_POLICY_TYPE = "WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1"
RESOURCE_POLICY_KEYS = {
    "policy_type", "wall_time_expiry_seconds", "clock", "starts_at",
    "accumulation", "checkpoint_semantics", "on_exhaustion",
    "scientific_early_stop", "candidate_count", "decision_basis",
}
RESOURCE_DECISION_BASIS_KEYS = {
    "source", "benchmark_sha256", "real_p5_labels_read_before_choice",
}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


def validate_resource_policy(value: Any) -> dict[str, Any]:
    """Validate the owner-late-bound, outcome-blind Wave-1 resource policy.

    Amendment D defines ``wall_time_expiry`` as a cumulative active-attempt
    duration in integer seconds.  It is deliberately distinct from the
    security credential's absolute ``expires_at`` timestamp.  The owner
    chooses the integer after the sealed synthetic benchmark and before the
    first P3 real-label access; this function never supplies a default.
    """
    if not isinstance(value, dict) or set(value) != RESOURCE_POLICY_KEYS:
        raise AuthorityError("RESOURCE_POLICY_EXACT_FIELDS_REQUIRED")
    if value["policy_type"] != RESOURCE_POLICY_TYPE:
        raise AuthorityError("RESOURCE_POLICY_TYPE_INVALID")
    seconds = value["wall_time_expiry_seconds"]
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds <= 0:
        raise AuthorityError("RESOURCE_POLICY_SECONDS_INVALID")
    expected = {
        "clock": "DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME",
        "starts_at": "WAVE1_APPLIED",
        "accumulation": "SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE",
        "checkpoint_semantics": "SEALED_PARTIAL_CHECKPOINT_RESUME_ONLY",
        "on_exhaustion": "RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED",
        "scientific_early_stop": False,
        "candidate_count": 174,
    }
    if any(value.get(key) != wanted for key, wanted in expected.items()):
        raise AuthorityError("RESOURCE_POLICY_SEMANTICS_INVALID")
    basis = value.get("decision_basis")
    if not isinstance(basis, dict) or set(basis) != RESOURCE_DECISION_BASIS_KEYS:
        raise AuthorityError("RESOURCE_POLICY_DECISION_BASIS_INVALID")
    if basis.get("source") != "SEALED_SYNTHETIC_FULL_PATH_BENCHMARK_ONLY":
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    if basis.get("real_p5_labels_read_before_choice") is not False:
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    digest = basis.get("benchmark_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(
            c not in "0123456789abcdef" for c in digest):
        raise AuthorityError("RESOURCE_POLICY_BENCHMARK_HASH_INVALID")
    return value


def resource_policy_sha256(value: Any) -> str:
    validate_resource_policy(value)
    return sha256(canonical_json(value))


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: dict[str, Any] | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
            validate_resource_policy(self.resource_scope)
        elif self.resource_scope is not None:
            raise AuthorityError("RESOURCE_POLICY_ONLY_ALLOWED_FOR_WAVE1")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if type(self.peer_uid) is not int or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or type(self.ledger_sequence) is not int:
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)

